tool_input.command:
cd "C:\Users\Administrator\Documents\deepseek-harness\default-workspace\mmvp-bench"
Write-Host "=== python process commandlines ==="
Get-CimInstance Win32_Process -Filter "Name='python3.exe' OR Name='python.exe'" -ErrorAction SilentlyContinue | ForEach-Object {
  $cmd=$_.CommandLine; if($cmd -and $cmd.Length -gt 5){ Write-Host "$($_.ProcessId): $cmd" }
}
Write-Host "=== cursor-grok result dir ==="
$dirs = Get-ChildItem results -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'cursor*' }
$dirs | ForEach-Object { Write-Host $_.Name; Get-ChildItem $_.FullName -ErrorAction SilentlyContinue | ForEach-Object { Write-Host "   $($_.Name) $((Get-Item $_.FullName).Length) bytes" } }
Write-Host "=== any error in orch_cursor.log? ==="
Select-String -Path orch_cursor.log -Pattern "Error|429|Timeout|Exception" -ErrorAction SilentlyContinue | Select-Object -First 5
